<template>
  <div class="content">
    <div class="container-fluid">
      <div class="card">

        <div class="card-header">
          <router-link to="/select-option" class="btn btn-default btn-simple">
            <i class="fa fa-arrow-left"></i> <span class="card-title">Back</span>
          </router-link>
        </div>

        <div class="card-body">

          <h2>SQAaaS lets you create customized CI/CD pipelines</h2>

          <div class="criteria-description">
            <div class="text">
              <div class="title">Quality criteria define the CI/CD pipeline work</div>
              <div>It is the underpinning part where the pipeline’s purpose takes shape.</div>
              <div>The associated properties for each criterion will be displayed once selected in the dropdown list below.</div>
            </div>
            <img class="icon" src="../../static/criteria.png" alt="Quality criteria">
          </div>

          <div class="pipeline-name">
            <div class="title">Choose a name for the pipeline</div>
