          <div class="custom_envs">

            <base-checkbox class="custom_envs_checkbox" label="Customize Environment"  help="Define here the environment variables that will be furtherly used by the pipeline" link="https://docs.sqaaas.eosc-synergy.eu/pipeline_as_a_service/step_1_repositories#environment" v-model="custom_env.checkbox" />

            <div v-if="custom_env.checkbox">

              <div class="custom_envs_input">
