                <base-input class="custom_env_input_value" type="text" required label="Value" addon-left-icon="fa fa-align-left" v-model="custom_env.input.value" />
                <button class="btn btn-primary btn-fill custom_env_add" @click="addCustomEnv()"><i class="fa fa-plus"></i> Add</button>
                <div v-show="custom_env.error_input" class="error"> <i class="fa fa-exclamation-triangle"></i> Error: Key and value are required</div>
              </div>

              <div v-if="this.custom_env.added.length > 0" class="custom_envs_added">
                <div class="title">Configured Environment</div>

                <div v-for="(env, index) in this.custom_env.added" class="custom_envs_list">
                  <div class="custom_env_key_value">{{ env.key }}: {{ env.value }}</div>
                  <button type="button" class="btn-simple btn btn-xs custom_env_delete" @click="removeCustomEnv(index)"><i class="fa fa-trash"></i></button>
                </div>
              </div>

            </div>
          </div>

          <div class="criteria">

           <div class="row">
             <div class="col-xl-6 criteria-input">

               <div class="title">Criteria and Tools Selection</div>

               <label>Choose a Criterion</label>
               <div v-if="!api_criteria.length > 0" class="ssc-head-line" />
                <div v-else class="input-group">
                  <div class="input-group-prepend">
                    <span class="input-group-text"> <i class="fa fa-compass"></i> </span>
                  </div>
                  <select class="custom-select criteria_list" v-model='criteria.criterion_selected'>
                    <option v-show="criteria.criterion_selected" value="">None</option>
                    <option disabled class="criteria_input_section">Software</option>
                    <option v-for="(criteria,key) in api_criteria" v-if="criteria.type === 'software'" :key="key" :value="criteria">{{criteria.id}}</option>
                    <option disabled class="criteria_input_section">Service</option>
                    <option v-for="(criteria,key) in api_criteria" v-if="criteria.type === 'service' && criteria.id !== 'SvcQC.Fun'" :key="key" :value="criteria">{{criteria.id}}</option> <!-- SvQC.Fun has not been tested yet -->
                  </select>
                </div>


                <div v-if="criteria.criterion_selected">
                  <div class="criteria_info">
                    <div><span class="badge badge-info">Scope</span> {{ criteria.criterion_selected.description.msg }} (<a :href="criteria.criterion_selected.description.docs" target="_blank">more details</a>)</div>
                    <div><span class="badge badge-info">Improves</span> {{ criteria.criterion_selected.description.improves }}</div>
                  </div>


                  <div class="tool">
                    <div class="tool_input">
                      <label>Choose a tool</label>
                      <div class="input-group">
                        <div class="input-group-prepend">
                          <span class="input-group-text"> <i class="fa fa-cogs"></i> </span>
                        </div>
                        <select class="custom-select" v-model='criteria.tool.selected'>
                          <option v-for="(tool,key) in criteria.tool.available" :key="key" :value="tool">{{tool.name.toUpperCase()}}</option>
                        </select>
                      </div>
                    </div>


                    <div v-if="criteria.tool.selected">

                      <div class="tool_badges">
                        <span v-if="criteria.tool.custom_image.name" class="badge badge-secondary">image: {{criteria.tool.custom_image.name}}</span>
                        <span v-else>
                          <span v-if="criteria.tool.selected.docker.image" class="badge badge-secondary">image: {{ criteria.tool.selected.docker.image }}</span>
                          <span v-else-if="criteria.tool.selected.docker.dockerfile" class="badge badge-secondary">image: {{ criteria.tool.selected.docker.dockerfile }}</span>
                          <span v-if="criteria.tool.selected.lang" class="badge badge-primary">lang: {{ criteria.tool.selected.lang }}</span>
                          <span v-if="criteria.tool.selected.version" class="badge badge-danger">version: {{ criteria.tool.selected.version }}</span>
                        </span>
                      </div>

                      <div class="external_repo">

                        <base-checkbox class="external_repo_checkbox" label="My tool needs code from external repository"  help="External repository is different from the one that will contain the current pipeline" link="https://docs.sqaaas.eosc-synergy.eu/pipeline_as_a_service/step_1_repositories#defining-repositories" v-model="criteria.tool.external_repo.checkbox" />

                        <div v-if="criteria.tool.external_repo.checkbox">

                          <div class="external_repo_input">

                            <div v-if="externalReposCollection.length > 0" class="external_repo_collection dropdown">
                              <button class="btn btn-secondary dropdown-toggle" type="button" data-toggle="dropdown"> Previous repos</button>
                              <div class="dropdown-menu">
                                <a v-for="repo in externalReposCollection" class="dropdown-item" @click="addRepoInput(repo)"> {{repo.url}} {{repo.branch? "/ "+repo.branch : ""}} </a>
                              </div>
                            </div>

                            <base-input class="external_repo_input_url" type="text" required label="Repository URL" addon-left-icon="fa fa-archive" help="The URL you can use to clone the project" v-model="criteria.tool.external_repo.url" />
                            <base-input class="external_repo_input_branch" type="text" label="Branch" placeholder="master" addon-left-icon="fa fa-code-fork" v-model="criteria.tool.external_repo.branch" />
                          </div>
                          <div class="public_repo"><i class="fa fa-bell"></i> Repository must be public for the checkout to work</div>

                        </div>
                      </div>

                      <div class="tool_args">
                        <div v-for="arg in (criteria.tool.selected.args || []).filter(arg => arg.selectable)" :key="arg.id">

                            <div v-if="arg.format === 'string' && !arg.repeatable" class="form-group">
                              <base-input type="text" :label="arg.description" :required="arg.type === 'positional'" v-model="arg.value" />
                            </div>

                            <div v-else-if="arg.format === 'string' && arg.repeatable" class="form-group">
                              <base-input type="text" :label="arg.description" :required="arg.type === 'positional'" v-model="arg.value" tags />
                            </div>

                            <div v-else-if="arg.format === 'array' && !arg.repeatable" class="form-group">
                              <label :for="arg.id"><span v-if="arg.type === 'positional'" class="required">*</span> {{arg.description}}</label>
                              <select class="custom-select" :id="arg.id" v-model="arg.inputValue">
                                <option selected disabled value=''></option>
                                <option v-for="opt in arg.value" :key="opt" :value="opt">{{opt}}</option>
                              </select>
                            </div>

                        </div>
                      </div>

                      <div class="custom_image">

                        <base-checkbox class="custom_image_checkbox" label="My tool needs a custom public image" help="Define your own image service. This has to be public." v-model="criteria.tool.custom_image.checkbox"/>

                        <div v-if="criteria.tool.custom_image.checkbox">
                          <div class="custom_image_input">
                            <base-input type="text" label="Custom public image" addon-left-icon="fa fa-box" :placeholder="criteria.tool.selected.docker.image" v-model="criteria.tool.custom_image.name" />
                          </div>
                        </div>
                      </div>

