                      <div v-show="criteria.tool.error_tool_already_selected" class="error"> <i class="fa fa-exclamation-triangle"></i> Error: This tool has already been selected for its criterion. Please, delete it before add a new one</div>

                      <button type="button" class="btn btn-primary btn-fill add_tool_button" @click="addTool()"><i class="fa fa-plus"></i> Add {{criteria.tool.selected.name}} tool for {{criteria.criterion_selected.id}} criterion</button>

