                        <div v-if="tool.external_repo.url" class="tool_data"> <span class="tool_data_title">External repo:</span> {{tool.external_repo.url}}/{{tool.external_repo.branch}}</div>
                        <div v-for="arg in tool.tool.args">
                          <div v-if="arg.selectable && arg.format === 'string' && arg.value" class="tool_data"> <span class="tool_data_title">{{arg.description}}:</span> {{arg.value}}</div>
                          <div v-else-if="arg.selectable && arg.format === 'array' && arg.value" class="tool_data"> <span class="tool_data_title">{{arg.description}}:</span> {{arg.inputValue}}</div>
                        </div>
