                    No criteria selected yet
                  </div>

             </div>

           </div>


        </div>

          <button class="btn btn-primary btn-fill create-pipeline-button" @click="createPipeline()" type="button" :disabled="criteria.added.length === 0">Create pipeline</button>

        </div>

