<script>

import Services from "../services/services";
  export default {

    components: {},
    mixins: [Services],

    data () {
      return {
        api_criteria: [], // Criteria data from API
        pipeline_name: '', // Name of the pipeline
        error_pipeline_name: false, // Pipeline name is required

        // Custom environment
        custom_env:{
          checkbox: false, // Panel is displayed?
          input: { // Input fields
            key: '',
            value: ''
          },
          error_input: false, // Key and value are required
          added : [] // Total env vars added
          /*
          [{
            key: String,
            value: String
          }]
          */
        },

        // Criteria
        criteria: {
          criterion_selected: undefined, // Criterion (object) selected from drop-down list

          // Tool
          tool: {
            available: [], // Tools available for selected criteria
            selected: undefined, // Tool (object) selected from drop-down list
            // External Repository
            external_repo: { // External repository for the tool
              checkbox: false, // Panel is displayed?
              url: '',
              branch: ''
            },

            // Custom Image
            custom_image:{
              checkbox: false, // Panel is displayed?
              name: '', // Image that replaces tool default image
            },

            error_args: false, // Some tool arguments are required
            error_tool_already_selected: false // The tool has already been selected for its criterion
          },
          added: [] // Set of criteria and tools selected
          /*
          [{
            criterionID: String,
            tools: [{
              tool: Tool,
              repo: {url: String, branch: String},
              image: String
            }]
          }]
          */
        }

      }
    },

    created(){
      this.getCriteriaCall(this.getCriteriaCallBack) // Get data from API
    },
    mounted(){
      $('[data-toggle="tooltip"]').tooltip()

      // Set mutation observer for create Bootstrap Tooltip on dynamics ones
      const targetNode = document.getElementsByClassName("criteria")[0];
      const config = { attributes: true, childList: true, subtree: true };
      const callback = (mutationList, observer) => { $('.criteria [data-toggle="tooltip"]').tooltip() };
      const observer = new MutationObserver(callback);
      observer.observe(targetNode, config);
    },

    computed: {
      validPipelineName(){
        const regex = new RegExp("(^$)|^[a-zA-Z0-9_.-]+$");
        return regex.test(this.pipeline_name)
      },
      externalReposCollection(){
        // Total external repositories added during the tools configuration
        let external_repositories =  this.criteria.added.flatMap(criteria => criteria.tools.flatMap(tool => tool.external_repo.url.trim()? tool.external_repo : []))
        // Remove duplicates
        return external_repositories.filter((repo1, index, array) => array.findIndex(repo2 => (repo1.url === repo2.url && repo1.branch === repo2.branch)) === index )
      }
    },

    watch:{
      'pipeline_name'(val){
        if(val) this.error_pipeline_name = false;
      },
      'criteria.tool.external_repo.url'(val){
        if(val) this.criteria.tool.external_repo.error_input_url = false;
      },
      'custom_env.input.key'(val){
        if(val) this.custom_env.error_input = false;
      },
      'custom_env.input.value'(val){
        if(val) this.custom_env.error_input = false;
      },
      'criteria.criterion_selected'(criterion_selected){
        this.criteria.tool.external_repo.checkbox = false
        this.criteria.tool.external_repo.url = ""
        this.criteria.tool.external_repo.branch = ""
        this.criteria.tool.custom_image.checkbox = false
        this.criteria.tool.custom_image.name = ''
        this.criteria.tool.selected = undefined
        this.criteria.tool.available = criterion_selected ? this.api_criteria.find(criterion => criterion.id === criterion_selected.id).tools : []
        this.criteria.tool.error_args = false
      },
      'criteria.tool.selected'(tool_selected){
        this.criteria.tool.error_args = false
      }
    },

    methods:{
      getCriteriaCallBack(response){

        if(response.status === 200){ // 200 OK
          this.api_criteria = response.data;
        }else{
          this.$swal.fire({
            title: 'We are having problems making the request.',
            html: '<div style="font-size: 0.85em">' + response.status + " " + response.statusText + " " + response.config.method.toUpperCase() + " " + response.config.url + '</div>' +
                  '<div style="margin-top: 1.5em">Please, try again in a few minutes.</div>',
            icon: 'error',
            confirmButtonText: 'Close',
            confirmButtonColor: '#E14726',
            footer: '<a style="font-size:18px;color:red; text-decoration:underline;"  href="https://github.com/EOSC-synergy/SQAaaS/issues/new/choose" target="_blank">Report the issue</a>',
          }).then(() => {
            this.$router.push('select-option');
          })
        }
      },

      addCustomEnv(){
        if(!this.custom_env.input.key || !this.custom_env.input.value){
          this.custom_env.error_input = true;
        }else{
          this.custom_env.error_input = false;

          this.custom_env.added.push(
            {
              'key': this.custom_env.input.key.trim(),
              'value': this.custom_env.input.value.trim(),
            }
          )

          this.custom_env.input.key = '';
          this.custom_env.input.value = '';

        }
      },
      removeCustomEnv(index){
        this.custom_env.added.splice(index,1);
      },

      addRepoInput(repo){

        this.criteria.tool.external_repo.url = repo.url
        this.criteria.tool.external_repo.branch = repo.branch
      },

      addTool(){

        if(this.criteria.tool.selected.args && this.criteria.tool.selected.args.filter(arg => arg.type === 'positional').some(arg => (arg.format === "string" && !arg.value.trim()) || (arg.format === "array" && (!arg.inputValue || !arg.inputValue.trim())))){
          this.criteria.tool.error_args = true
          return
        }

        this.criteria.tool.error_args = false
        this.criteria.tool.error_tool_already_selected = false

        let criteria_exist = this.criteria.added.find( criteria => criteria.criterionID === this.criteria.criterion_selected.id)

        if(!criteria_exist){
          this.criteria.added.push({
            criterionID: this.criteria.criterion_selected.id,
            tools: [{
              tool: this.criteria.tool.selected,
              external_repo: {url: this.criteria.tool.external_repo.url, branch: this.criteria.tool.external_repo.branch},
              image: this.criteria.tool.custom_image.name
            }]
          })

        }
        else{
          let tool_exists = criteria_exist.tools.find( tool => tool.tool.name === this.criteria.tool.selected.name)
          if(tool_exists){
            this.criteria.tool.error_tool_already_selected = true
            return
          }
          criteria_exist.tools.push({
            tool: this.criteria.tool.selected,
            external_repo: {url: this.criteria.tool.external_repo.url, branch: this.criteria.tool.external_repo.branch},
            image: this.criteria.tool.custom_image.name
          })
        }


        this.criteria.tool.external_repo.checkbox = false
        this.criteria.tool.external_repo.url = ""
        this.criteria.tool.external_repo.branch = ""
        this.criteria.tool.custom_image.checkbox = false
        this.criteria.tool.custom_image.name = ''
        this.criteria.tool.selected = undefined
        this.criteria.criterion_selected = undefined

      },
      removeTool(criterion_index, tool_index){

        this.criteria.added[criterion_index].tools.splice(tool_index,1)
        if(this.criteria.added[criterion_index].tools.length === 0) this.criteria.added.splice(criterion_index,1)

      },

      createPipeline(){

        this.error_pipeline_name = false

        if(!this.pipeline_name.trim()){
          this.error_pipeline_name = true
          document.getElementsByClassName('pipeline-name')[0].scrollIntoView({ block: "center", behavior: "smooth" });
          return
        }

        // Replace array value by string inputValue on criteria.tool.tool.args
        for (const criteria of this.criteria.added) {
          for(const tool of criteria.tools){
            for(const arg of tool.tool.args){
              if (Array.isArray(arg.value)) arg.value = arg.inputValue
            }
          }
        }


        this.$store.state.criteria = {
          pipeline_name: this.pipeline_name,
          external_repos: this.externalReposCollection,
          custom_env: this.custom_env.added,
          criteria: this.criteria.added
        }

        this.$router.push({name: 'Files'});

      }
    }
}

</script>

